        if (c == '\\') { 
            i++; 
            if (i >= str.length()) { 
                throw new Exception("Trailing backslash"); 
            } 
            c = str.charAt(i); 
            switch (c) { 
                case 'b': 
                    sb.append('\b'); 
                    break; 
                case 't': 
                    sb.append('\t'); 
                    break; 
