                    sb.append('\f'); 
                    break; 
                case 'r': 
                    sb.append('\r'); 
                    break; 
                case '\"': 
                    sb.append('\"'); 
                    break; 
                case '\'': 
                    sb.append('\''); 
                    break; 
                case '\\': 
                    sb.append('\\'); 
                    break; 
                default: 
                    throw new Exception("Unknown escape sequence: \\" + c); 
            } 
        } else { 
            sb.append(c); 
        } 
    } 
    return sb.toString(); 
}

